 static String read(InputStream in)throws Exception{try(InputStream i=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1){out.write(b,0,n);if(out.size()>8*1024*1024)throw new IOException("response too large");}return out.toString("UTF-8");}}
