 void reload(){generation++;page=0;total=0;items.clear();adapter.notifyDataSetChanged();grid.setSelection(0);loading=false;loadMore();}
 void loadMore(){if(loading||closed)return;loading=true;final int token=generation,next=page+1,cat=category;final String ord=order,ar=area,ge=genre;status.setText("正在加载…");worker.execute(()->{JSONObject result=null;boolean remote=false;String error="";try{String url=api();if(!url.startsWith("http://")&&!url.startsWith("https://"))throw new IOException("未配置木子片库");JSONObject f=new JSONObject();f.put("order",ord);f.put("area",ar);f.put("genre",ge);result=new JSONObject(fetch(url+(url.contains("?")?"&":"?")+"ac=detail&t="+IDS[cat]+"&pg="+next+"&f="+URLEncoder.encode(f.toString(),"UTF-8")));if(result.optInt("code",1)!=1)throw new IOException(result.optString("msg"));JSONArray filters=result.optJSONObject("filters")==null?null:result.optJSONObject("filters").optJSONArray(IDS[cat]);boolean supportsGenre=false;if(filters!=null)for(int fi=0;fi<filters.length();fi++)if("genre".equals(filters.getJSONObject(fi).optString("key")))supportsGenre=true;if(!supportsGenre||result.optJSONArray("list")==null)throw new IOException("片库接口需要升级");remote=true;}catch(Exception e){android.util.Log.e(TAG,"catalog load failed",e);error="片库未连接";try{JSONArray snapshot=new JSONArray(read(activity.getAssets().open("muzi-catalog.json")));result=localPage(snapshot,IDS[cat],ord,ar,ge,next);}catch(Exception ignored){}}
 final JSONObject r=result;final boolean live=remote;final String msg=error;post(()->{if(closed||token!=generation)return;loading=false;if(r==null){status.setText("读取失败，请按确认重试");return;}if(page>0&&online!=live){status.setText("连接状态变化，请在我的菜单刷新片库");total=items.size();return;}online=live;JSONArray list=r.optJSONArray("list");if(list!=null)for(int i=0;i<list.length();i++)items.add(list.optJSONObject(i));page=next;total=r.optInt("total",items.size());adapter.notifyDataSetChanged();status.setText((live?"":"离线样本 · "+msg+" · ")+"已加载 "+items.size()+" / "+total+" 部"+(items.isEmpty()?" · 暂无匹配内容":" · 向下继续浏览"));});});}
 static JSONObject localPage(JSONArray data,String kind,String order,String area,String genre,int page)throws Exception{ArrayList<JSONObject> chosen=new ArrayList<JSONObject>();for(int i=0;i<data.length();i++){JSONObject x=data.getJSONObject(i);if(!kind.equals(x.optString("_kind")))continue;if(!area.equals("全部")&&!area.equals(kind.equals("17")?sportOf(x):x.optString("_region")))continue;if(!genre.equals("全部")){JSONArray gs=x.optJSONArray("_genres");boolean has=false;if(gs!=null)for(int g=0;g<gs.length();g++)if(genre.equals(gs.optString(g)))has=true;if(!has)continue;}if(order.equals("recommend")&&x.optDouble("vod_douban_score",0)<7)continue;if(order.equals("hot")&&x.optDouble("vod_hits_week",0)<=0)continue;chosen.add(x);}Collections.sort(chosen,(a,b)->{String key=order.equals("hot")?"vod_hits_week":"vod_douban_score";int metric=order.equals("latest")?0:Double.compare(b.optDouble(key,0),a.optDouble(key,0));return metric!=0?metric:b.optString("vod_time").compareTo(a.optString("vod_time"));});HashSet<String> seen=new HashSet<String>();ArrayList<JSONObject> unique=new ArrayList<JSONObject>();for(JSONObject x:chosen)if(seen.add(x.optString("vod_name")+"|"+x.optString("vod_year")))unique.add(x);JSONArray rows=new JSONArray();for(int i=(page-1)*24;i<Math.min(page*24,unique.size());i++)rows.put(unique.get(i));return new JSONObject().put("list",rows).put("total",unique.size());}
