 void loadPoster(final ImageView image,final TextView title,final String url){image.setTag(url);if(!url.startsWith("http"))return;android.graphics.Bitmap saved=cache.get(url);if(saved!=null){image.setImageBitmap(saved);title.setVisibility(GONE);return;}images.execute(()->{HttpURLConnection c=null;try{c=LegacyTls.open(url);c.setConnectTimeout(4000);c.setReadTimeout(6000);byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>3*1024*1024)throw new IOException("poster too large");}bytes=out.toByteArray();}android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>360||o.outHeight/o.inSampleSize>520)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=android.graphics.Bitmap.Config.RGB_565;final android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap!=null){cache.put(url,bitmap);post(()->{if(!closed&&url.equals(image.getTag())){image.setImageBitmap(bitmap);title.setVisibility(GONE);}});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});}
