 static HomeSurface find(Activity a){return (HomeSurface)a.findViewById(android.R.id.content).findViewWithTag(TAG);}
 public static void install(Activity a){if(find(a)!=null){entry(a,a.getIntent());return;}ViewGroup content=(ViewGroup)a.findViewById(android.R.id.content);try{HomeSurface surface=new HomeSurface(a);for(int i=0;i<content.getChildCount();i++)content.getChildAt(i).setVisibility(GONE);content.addView(surface,new ViewGroup.LayoutParams(-1,-1));entry(a,a.getIntent());}catch(Exception e){for(int i=0;i<content.getChildCount();i++)content.getChildAt(i).setVisibility(VISIBLE);android.util.Log.e(TAG,"original home retained",e);}}
 public static void entry(Activity a,Intent intent){HomeSurface s=find(a);if(s==null||intent==null)return;String mode=intent.getStringExtra("muzi_entry");intent.removeExtra("muzi_entry");if(!"live".equals(mode)){s.livePending=false;s.setVisibility(VISIBLE);s.renderFilters();return;}s.livePending=true;s.liveDeadline=SystemClock.uptimeMillis()+30000;s.heading.setText("正在打开直播电视…");s.prepareLive();s.tryLive();}
 void prepareLive(){if(liveBootstrapping||closed)return;liveBootstrapping=true;new Thread(()->{try{Object cfg=Class.forName("P2.d").getField("a").get(null);if(!((Boolean)call(call(cfg,"e"),"isEmpty")))return;Object saved=Class.forName("com.fongmi.android.tv.bean.Config").getMethod("live").invoke(null);String url=(String)call(saved,"getUrl");if(!url.startsWith("https://")&&!url.startsWith("http://"))return;String raw=fetch(url);if(closed||!livePending)return;if(!((Boolean)call(call(cfg,"e"),"isEmpty")))return;cfg.getClass().getMethod("l",String.class,Class.forName("M2.a")).invoke(cfg,raw,null);}catch(Exception e){android.util.Log.w(TAG,"live configuration load failed",e);}finally{liveBootstrapping=false;}},"muzi-live-setup").start();}
 void tryLive(){if(!livePending||closed)return;try{Object cfg=Class.forName("P2.d").getField("a").get(null);Object live=call(cfg,"e");if(!((Boolean)call(live,"isEmpty"))){livePending=false;openLive();return;}}catch(Exception e){android.util.Log.d(TAG,"waiting for live configuration",e);}if(SystemClock.uptimeMillis()>=liveDeadline){livePending=false;new AlertDialog.Builder(activity).setMessage("直播配置尚未就绪，请检查原直播源或网络后重试。").setPositiveButton("重试",(d,w)->{livePending=true;liveDeadline=SystemClock.uptimeMillis()+30000;prepareLive();tryLive();}).setNeutralButton("设置",(d,w)->openActivity("SettingActivity")).setNegativeButton("返回桌面",(d,w)->activity.finish()).show();return;}postDelayed(()->tryLive(),300);}
 public static void configured(Activity a){HomeSurface s=find(a);if(s!=null&&!s.closed)s.reload();}
